"""Receipt primitives; importing this module never starts a probe or build."""
from __future__ import annotations
from datetime import datetime, timezone
import hashlib
import json
import math
from pathlib import Path
import subprocess
import time
import uuid

D = Path(__file__).resolve().parent
ROOT = D.parents[1]

def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

def save(path: Path, value: object) -> None:
    tmp = path.with_suffix(path.suffix + '.tmp')
    tmp.write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False), encoding='utf8')
    tmp.replace(path)

def read(path: Path):
    return json.loads(path.read_text(encoding='utf-8-sig'))

def identity(probe: str, tag: str) -> dict:
    source = D / ('differential.rs' if probe == 'differential' else probe + '_probe.rs')
    binary = D / f'{probe}-{tag}.exe'
    linked = D / f'identity-{probe}-{tag}.json'
    link = read(linked)
    if sha(source) != link['sourceSha256'] or sha(binary) != link['executableSha256']:
        raise ValueError(f'Probe identity mismatch: {probe}/{tag}')
    if probe == 'differential':
        argv = link['compilerArguments']
        if not any(argv[i:i+2] == ['--cfg', 'borrowed_result'] for i in range(len(argv)-1)):
            raise ValueError('Differential probe was not linked with owned/view assertions')
    if tag == 'before':
        archive = read(D / 'before-binary-identity.json')
        if archive['probes'][probe]['binarySha256'] != sha(binary):
            raise ValueError('Inherited baseline binary differs from archival receipt')
        origin = D / f'origin-{probe}-link.json'
        if sha(origin) != link['originSha256'] or read(origin)['executableSha256'] != sha(binary):
            raise ValueError('Baseline role conversion has lost its original link identity')
        for path, expected in link['libraryHashes'].items():
            entry = archive['libraries'][path]
            if entry['sha256'] != expected or sha(Path(entry['archive'])) != expected:
                raise ValueError(f'Archived baseline library mismatch: {path}')
    else:
        for path, expected in link['libraryHashes'].items():
            if sha(ROOT / path) != expected:
                raise ValueError(f'After linked library mismatch: {path}')
    return {'binary': str(binary), 'binarySha256': sha(binary), 'source': str(source),
            'sourceSha256': sha(source), 'linkReceipt': str(linked),
            'linkReceiptSha256': sha(linked), 'link': link}

def directory(prefix: str) -> Path:
    stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ') + '-' + uuid.uuid4().hex[:8]
    out = D / (prefix + '-receipts') / stamp
    out.mkdir(parents=True, exist_ok=False)
    return out

def execute(out: Path, stem: str, command: list[str], timeout: float) -> tuple[dict, bytes]:
    start = time.monotonic()
    try:
        p = subprocess.run(command, cwd=ROOT, capture_output=True, timeout=timeout)
        raw, errors, code = p.stdout, p.stderr, p.returncode
    except subprocess.TimeoutExpired as error:
        raw, errors, code = error.stdout or b'', error.stderr or b'', None
    stdout, stderr, exit_path = (out / (stem + x) for x in ('.stdout', '.stderr', '.exit.json'))
    stdout.write_bytes(raw)
    stderr.write_bytes(errors)
    row = {'command': command, 'returncode': code, 'wallSeconds': time.monotonic()-start,
           'stdout': str(stdout), 'stderr': str(stderr), 'exit': str(exit_path),
           'stdoutSha256': sha(stdout), 'stderrSha256': sha(stderr)}
    save(exit_path, {'command': command, 'returncode': code, 'timeoutSeconds': timeout if code is None else None})
    row['exitSha256'] = sha(exit_path)
    return row, raw

def reject_nonfinite(token):
    raise ValueError('Nonfinite JSON token: ' + token)

def snapshots(raw: bytes) -> list[dict]:
    lines = raw.splitlines()
    if len(lines) != 33 or any(not line for line in lines):
        raise ValueError('Expected one seed snapshot and 32 update snapshots')
    rows = [json.loads(line, parse_constant=reject_nonfinite) for line in lines]
    for i, row in enumerate(rows):
        if not isinstance(row, dict) or set(row) != {'snapshot', 'changes'} or not isinstance(row['snapshot'], dict):
            raise ValueError('Malformed differential record')
        if (i == 0 and row['changes'] is not None) or (i > 0 and not isinstance(row['changes'], dict)):
            raise ValueError('Malformed initial snapshot or update changes')
    return rows

def finite(value):
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (float, int)) or not math.isfinite(value):
        raise ValueError(f'Expected finite float or NA: {value!r}')
    return float(value)

def source(path: Path, text: str) -> dict:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and path.read_text(encoding='utf8') != text:
        raise ValueError(f'Frozen generated source differs: {path}')
    if not path.exists():
        path.write_text(text, encoding='utf8')
    return {'path': str(path), 'sha256': sha(path)}

