        "{\"schemaVersion\":9,\"fills\":[{\"id\":1,\"firstId\":1,\"secondId\":1,\"colors\":[null],\"gradient\":[{\"topValue\":null,\"bottomValue\":null,\"topColor\":-1,\"bottomColor\":null}]}]}",
        "{\"schemaVersion\":9,\"fills\":[{\"id\":1,\"firstId\":1,\"secondId\":1,\"colors\":[null],\"gradient\":[{\"topValue\":null,\"bottomValue\":null,\"topColor\":null,\"bottomColor\":null,\"extra\":true}]}]}",
        "{\"schemaVersion\":9,\"fills\":[{\"id\":1,\"firstId\":1,\"secondId\":1,\"colors\":[null],\"gradient\":[{\"bottomValue\":null,\"topColor\":null,\"bottomColor\":null}]}]}",
        "{\"schemaVersion\":9,\"fills\":[{\"id\":1,\"firstId\":1,\"secondId\":1,\"colors\":[],\"gradient\":[{\"topValue\":null,\"bottomValue\":null,\"topColor\":null,\"bottomColor\":null}]}]}",
    ];
