        "{\"visibility\":\"preview\",\"revision\":2,\"baseRevision\":1,\"schemaVersion\":2,\"series\":[{\"family\":\"plot\",\"id\":1,\"op\":\"other\",\"start\":0}]}",
        "{\"visibility\":\"confirmed\",\"revision\":2,\"baseRevision\":1,\"schemaVersion\":2,\"series\":[{\"family\":\"plot\",\"id\":1,\"op\":\"append\",\"start\":0,\"values\":[-0,1e-310,1e308,null]}]}",
        "{\"visibility\":\"preview\",\"revision\":2,\"baseRevision\":1,\"schemaVersion\":4,\"retainedFrom\":0,\"fills\":[{\"id\":1,\"action\":\"setGradient\",\"start\":0,\"values\":[{\"topValue\":true,\"bottomValue\":null,\"topColor\":null,\"bottomColor\":null}]}]}",
        "{\"visibility\":\"preview\",\"revision\":2,\"baseRevision\":1,\"schemaVersion\":4,\"retainedFrom\":0,\"fills\":[{\"id\":1,\"action\":\"setGradient\",\"start\":0,\"values\":[{\"topValue\":null,\"bottomValue\":null,\"topColor\":null,\"bottomColor\":null,\"extra\":0}]}]}",
    ];
    let mut cases = Vec::new();
    for input in full {
