"""Focused serialization stage receipts; never builds or links a probe.

One fresh process per scenario/version/repetition, alternating before/after.
Both raw output objects and subprocess receipts are retained independently.
"""
from __future__ import annotations
import argparse
from datetime import datetime, timezone
import hashlib
import json
import math
from pathlib import Path
import statistics
import struct
import subprocess
import time
import uuid

D = Path(__file__).resolve().parent
ROOT = D.parents[1]
STAGES = {
    "parseAnalyze", "seed", "resultMaterialization", "viewConstruction", "deltaConstruction",
    "ownedSink", "viewSink", "ownedVec", "viewVec", "ownedString", "viewString",
    "consumedSourceClone", "consumedString", "deltaSink", "deltaVec", "deltaString",
    "jsonParse", "jsonMapClone", "publicParse", "deltaJsonParse", "deltaJsonMapClone", "deltaPublicParse",
}
FIELDS = {"ms", "allocatedBytes", "allocations", "peakAdditionalLiveBytes", "liveDeltaBytes"}
TOP = {"schemaVersion", "scenario", "bars", "manualFixture", "deltaFixture", "fullBytes",
       "deltaBytes", "publicFullBytes", "publicDeltaBytes", "parserOutcomesCount", "fullProof", "deltaProof", "sinkWriteCalls", "byteEquality", "stages"}
RAW_FILES = {"full":"full.json", "delta":"delta.json", "publicFull":"full.public.json",
             "publicDelta":"delta.public.json", "parserOutcomes":"parser-outcomes.json"}

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def save(path, value):
    path = Path(path)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(value, ensure_ascii=False, allow_nan=False, indent=2), encoding="utf8")
    tmp.replace(path)

def pairs(items):
    value = {}
    for key, item in items:
        if key in value:
            raise ValueError("Duplicate JSON field: " + key)
        value[key] = item
    return value

def constant(token):
    raise ValueError("Nonfinite JSON token: " + token)

def scalar_int(token):
    # JSON's -0 token is integral lexically but carries a float sign on the wire.
    return -0.0 if token == "-0" else int(token)

def scalar_float(token):
    value = float(token)
    if not math.isfinite(value):
        raise ValueError("Out-of-f64-range JSON number: " + token)
    return value

def loads(raw):
    return json.loads(raw, object_pairs_hook=pairs, parse_constant=constant,
                      parse_int=scalar_int, parse_float=scalar_float)

def read(path):
    return loads(Path(path).read_text(encoding="utf-8-sig"))

def identity(tag, probe="serialization"):
    path = D / f"identity-{probe}-{tag}.json"
    link = read(path)
    binary = D / f"{probe}-{tag}.exe"
    source = D / f"{probe}_probe.rs"
    if sha(binary) != link["executableSha256"] or sha(source) != link["sourceSha256"]:
        raise ValueError("Serialization binary/source identity mismatch: " + tag)
    # Every linked library must be found at its recorded path or archived receipt.
    archive = read(D / "before-binary-identity.json") if tag == "before" else None
    manifest_path = D / ("before-source-identity.json" if tag == "before" else "source-identity.json")
    if link["sourceManifestSha256"] != sha(manifest_path):
        raise ValueError("Linked source manifest differs: " + tag)
    if archive is not None and archive["beforeManifestSha256"] != sha(manifest_path):
        raise ValueError("Archived baseline source manifest differs")
    for rawpath, expected in link["libraryHashes"].items():
        direct = Path(rawpath)
        direct = direct if direct.is_absolute() else ROOT / direct
        alternatives = [direct]
        if archive is not None:
            for key, item in archive["libraries"].items():
                if item["sha256"] == expected and (key == rawpath or Path(key).name == direct.name):
                    alternatives.append(Path(item["archive"]))
        if not any(p.exists() and sha(p) == expected for p in alternatives):
            raise ValueError("Linked library identity mismatch: " + rawpath)
    return {"binary":str(binary), "binarySha256":sha(binary), "sourceSha256":sha(source),
            "sourceManifestSha256":sha(manifest_path),
            "linkReceipt":str(path), "linkReceiptSha256":sha(path), "link":link}

def plan():
    return [
        {"name":"ordinary100k", "scenario":"ordinary", "bars":100000},
        {"name":"mixed20k", "scenario":"mixed", "bars":20000},
        {"name":"extreme20k", "scenario":"extreme", "bars":20000},
        {"name":"subnormal20k", "scenario":"subnormal", "bars":20000},
        {"name":"negative_zero20k", "scenario":"negative_zero", "bars":20000},
        {"name":"nonfinite20k", "scenario":"nonfinite", "bars":20000},
        {"name":"records4003", "scenario":"records", "bars":4003},
        {"name":"gradient4003", "scenario":"gradient", "bars":4003},
    ]

def prepare():
    source = D / "serialization-source.pine"
    text = '//@version=6\nindicator("serialization attribution")\nplot(close)\n'
    if source.exists() and source.read_text(encoding="utf8") != text:
        raise ValueError("Prepared source differs")
    if not source.exists():
        source.write_text(text, encoding="utf8")
    receipt = {"cases":plan(), "source":{"path":str(source), "sha256":sha(source)},
               "repetitionsPerVersion":3, "plannedProcesses":48, "stages":sorted(STAGES), "probesExecuted":False,
               "scope":"Focused serialization/parser stages, synthetic bulk deltas, not runtime-update or full resource qualification"}
    save(D / "serialization-plan.json", receipt)
    return receipt

def integer(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("Expected integer metric")
    return value

def metrics(raw, case):
    lines = raw.splitlines()
    if len(lines) != 1 or not lines[0]:
        raise ValueError("Expected one metrics JSON line")
    result = loads(lines[0])
    if not isinstance(result, dict) or set(result) != TOP:
        raise ValueError("Unknown/missing top-level metrics field")
    if result["schemaVersion"] != 1 or result["scenario"] != case["scenario"] or result["bars"] != case["bars"]:
        raise ValueError("Metrics scenario/bars/schema mismatch")
    if result["manualFixture"] is not (case["scenario"] in {"negative_zero", "nonfinite", "records", "gradient"}):
        raise ValueError("Metrics fixture classification differs")
    for field in ("fullBytes", "deltaBytes", "publicFullBytes", "publicDeltaBytes"):
        if integer(result[field]) <= 0:
            raise ValueError("Empty serialized object")
    if set(result["stages"]) != STAGES:
        raise ValueError("Unknown/missing stage")
    if integer(result["parserOutcomesCount"]) != 36:
        raise ValueError("Parser outcome corpus differs")
    if result["deltaFixture"] != "synthetic bulk append, drawing tail and strategy splice parser/encoder fixture; not runtime update qualification":
        raise ValueError("Unexpected delta fixture qualification")
    for name, stage in result["stages"].items():
        if set(stage) != FIELDS:
            raise ValueError("Unknown/missing stage metric: " + name)
        for key, value in stage.items():
            if isinstance(value, bool) or not isinstance(value, (float, int)) or not math.isfinite(value):
                raise ValueError("Nonfinite/nonnumeric stage metric")
            if key != "ms":
                integer(value)
            if key != "liveDeltaBytes" and value < 0:
                raise ValueError("Negative unsigned stage metric")
    if set(result["byteEquality"]) != {"ownedView", "ownedString", "viewString", "consumedString", "deltaString"}:
        raise ValueError("Missing byte proof")
    if not all(value is True for value in result["byteEquality"].values()):
        raise ValueError("Byte equality did not pass")
    for field in ("fullProof", "deltaProof"):
        proof = result[field]
        if set(proof) != {"finiteFloatBitsChecked", "nonfiniteNullsChecked", "negativeZeroBitsChecked", "inputBitsFnv64"}:
            raise ValueError("Malformed input-bit proof")
        for key in ("finiteFloatBitsChecked", "nonfiniteNullsChecked", "negativeZeroBitsChecked"):
            if integer(proof[key]) < 0:
                raise ValueError("Negative proof count")
        digest = proof["inputBitsFnv64"]
        if not isinstance(digest, str) or len(digest) != 16 or any(c not in "0123456789abcdef" for c in digest):
            raise ValueError("Invalid direct-input digest")
    return result

def equivalent(a, b, path="$"):
    # Integer identifiers remain exact. Float/integer lexical conversions are
    # compared as IEEE f64; the Rust probe separately checks original f64 bits.
    if isinstance(a, bool) or isinstance(b, bool):
        if type(a) is not type(b) or a != b:
            raise ValueError("Boolean differs at " + path)
    elif isinstance(a, (float, int)) and isinstance(b, (float, int)):
        if isinstance(a, int) and isinstance(b, int):
            if a != b:
                raise ValueError("Integer differs at " + path)
        elif struct.pack("!d", float(a)) != struct.pack("!d", float(b)):
            raise ValueError("Float bits differ at " + path)
    elif isinstance(a, dict) and isinstance(b, dict):
        if a.keys() != b.keys():
            raise ValueError("Object keys differ at " + path)
        for key in a:
            equivalent(a[key], b[key], path + "." + key)
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            raise ValueError("Array length differs at " + path)
        for i, (x, y) in enumerate(zip(a, b)):
            equivalent(x, y, path + f"[{i}]")
    elif type(a) is not type(b) or a != b:
        raise ValueError("Non-numeric field differs at " + path)

def run(out, stem, command, timeout):
    start = time.monotonic()
    try:
        p = subprocess.run(command, cwd=ROOT, capture_output=True, timeout=timeout)
        stdout, stderr, code = p.stdout, p.stderr, p.returncode
    except subprocess.TimeoutExpired as error:
        stdout, stderr, code = error.stdout or b"", error.stderr or b"", None
    o, e, x = (out / (stem + suffix) for suffix in (".stdout", ".stderr", ".exit.json"))
    o.write_bytes(stdout); e.write_bytes(stderr)
    save(x, {"command":command, "returncode":code, "timeoutSeconds":timeout if code is None else None})
    return {"command":command, "returncode":code, "wallSeconds":time.monotonic()-start,
            "stdout":str(o), "stdoutSha256":sha(o), "stderr":str(e), "stderrSha256":sha(e),
            "exit":str(x), "exitSha256":sha(x)}, stdout

def correctness_gates():
    manifest = read(D / "source-identity.json")
    changed = [path for path, expected in manifest["files"].items()
               if not (ROOT / path).is_file() or sha(ROOT / path) != expected]
    if changed:
        raise ValueError("Frozen runtime source changed: " + repr(changed))
    binding = {"manifestSha256":sha(D / "source-identity.json"),
               "archiveSha256":sha(D / "source.tar"), "files":len(manifest["files"]), "sourceVerified":True}
    result = {}
    for tag in ("windows", "linux"):
        p = D / f"gate-{tag}.exit"
        if int(p.read_text(encoding="utf-8-sig")) != 0:
            raise ValueError("Full gate did not pass: " + tag)
        phase = read(D / f"phase-gate-{tag}.json")
        if phase["status"] != "passed" or phase["returncode"] != 0 or phase["before"] != binding or phase["after"] != binding:
            raise ValueError("Full gate source binding differs: " + tag)
        if phase["gateLogSha256"] != sha(D / f"gate-{tag}.log") or phase["gateExitSha256"] != sha(p):
            raise ValueError("Full gate log/exit identity differs: " + tag)
        result[tag] = {"exitSha256":sha(p), "logSha256":sha(D / f"gate-{tag}.log")}
    text = subprocess.check_output(["powershell.exe", "-NoProfile", "-Command",
        'Get-Process | Where-Object { $_.ProcessName -match "^(cargo|rustc|maturin|link|cl|msbuild|pine.*|serialization.*|capacity.*|heap.*|differential.*)$" } | Select-Object ProcessName,Id | ConvertTo-Json']).decode("utf8").strip()
    if text:
        raise ValueError("Build/validation process still active: " + text)
    return {"gates":result, "sourceBinding":binding,
            "matchingWindowsBuildProcesses":[],
            "limitation":"Coordinator also keeps WSL compilation and other measurements quiescent; this does not prove OS inactivity."}

def summarize(cases, records):
    summary = {}
    for case in cases:
        by_tag = {tag:[r for r in records if r["case"] == case["name"] and r["tag"] == tag] for tag in ("before", "after")}
        if any(len(v) != 3 for v in by_tag.values()):
            raise ValueError("Incomplete repetition set")
        all_rows = by_tag["before"] + by_tag["after"]
        proof = all_rows[0]["metrics"]["fullProof"]
        delta_proof = all_rows[0]["metrics"]["deltaProof"]
        for row in all_rows:
            if row["metrics"]["fullProof"] != proof or row["metrics"]["deltaProof"] != delta_proof:
                raise ValueError("Input semantic proof differs between versions/repetitions")
        stages = {}
        for stage in sorted(STAGES):
            stages[stage] = {}
            for metric in sorted(FIELDS):
                b = [r["metrics"]["stages"][stage][metric] for r in by_tag["before"]]
                a = [r["metrics"]["stages"][stage][metric] for r in by_tag["after"]]
                bm, am = statistics.median(b), statistics.median(a)
                stages[stage][metric] = {"beforeSamples":b, "afterSamples":a,
                    "beforeMedian":bm, "afterMedian":am, "afterBeforeRatio":am/bm if bm else None}
        size = {key:{tag:[r["metrics"][key] for r in by_tag[tag]] for tag in by_tag}
                for key in ("fullBytes", "deltaBytes", "publicFullBytes", "publicDeltaBytes")}
        summary[case["name"]] = {"scenario":case["scenario"], "bars":case["bars"],
            "stages":stages, "serializedBytes":size, "fullProof":proof, "deltaProof":delta_proof,
            "parserOutcomesPerProcess":36, "beforeAfterExactRawBytes":True}
    return summary

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--prepare-only", action="store_true")
    ap.add_argument("--timeout", type=float, default=300)
    args = ap.parse_args()
    prepared = prepare()
    if args.prepare_only:
        print("Prepared 8 cases / 48 processes / 22 stages; no builds or probes executed.")
        return
    quiet = correctness_gates()
    identities = {tag:identity(tag) for tag in ("before", "after")}
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + "-" + uuid.uuid4().hex[:8]
    out = D / "serialization-receipts" / stamp
    out.mkdir(parents=True, exist_ok=False)
    receipt = {"status":"running", "plannedProcesses":48, "method":"8 focused cases, 3 fresh processes per version, alternating before/after order; 22 independently measured stages",
        "quiescence":quiet, "identities":identities, "runnerSha256":sha(Path(__file__)),
        "cases":prepared["cases"], "source":prepared["source"], "records":[],
        "limits":["Requested allocation sizes exclude allocator overhead; no whole-process peak claim.",
                  "Synthetic bulk delta is a parser/encoder fixture, not realtime execution proof.",
                  "DOM object clone measures the removed deep-copy operation separately. Timing differences are not attributed by subtraction.",
                  "Public from_json timing includes serde parse, owned typed materialization and DOM disposal. No new borrowed public API is measured.",
                  "Manual fixture result materialization includes fixture creation; seed is deliberately empty.",
                  "Raw JSON bytes are saved after measurement; output and JSON parse heaps are attributed separately.",
                  "Descriptive three-sample medians, not full-resource qualification."]}
    try:
        for repetition in range(3):
            for case in prepared["cases"]:
                pair = {}
                for tag in (("before", "after") if repetition % 2 == 0 else ("after", "before")):
                    stem = f'{case["name"]}-{tag}-{repetition}'
                    rawdir = out / stem
                    command = [identities[tag]["binary"], case["scenario"], str(case["bars"]), prepared["source"]["path"], str(rawdir)]
                    run_receipt, raw = run(out, stem, command, args.timeout)
                    row = {"case":case["name"], "tag":tag, "repetition":repetition, "run":run_receipt}
                    receipt["records"].append(row); save(out / "progress.json", receipt)
                    if run_receipt["returncode"] != 0:
                        raise RuntimeError("Serialization process failed: " + stem)
                    row["metrics"] = metrics(raw, case)
                    row["rawJson"] = {}
                    for kind, filename in RAW_FILES.items():
                        path = rawdir / filename
                        raw_json = path.read_bytes()
                        if kind != "parserOutcomes" and len(raw_json) != row["metrics"][kind + "Bytes"]:
                            raise ValueError("Recorded JSON length differs")
                        parsed = loads(raw_json) # strict duplicate/nonfinite rejection
                        if kind == "parserOutcomes":
                            if set(parsed) != {"schemaVersion", "cases"} or parsed["schemaVersion"] != 1 or len(parsed["cases"]) != 36:
                                raise ValueError("Malformed parser outcome corpus")
                        row["rawJson"][kind] = {"path":str(path), "sha256":sha(path), "bytes":len(raw_json)}
                    pair[tag] = row
                    save(out / "progress.json", receipt)
                    print(stem, "fullBytes", row["metrics"]["fullBytes"], "publicParseMs", row["metrics"]["stages"]["publicParse"]["ms"], flush=True)
                for kind in RAW_FILES:
                    b = Path(pair["before"]["rawJson"][kind]["path"]).read_bytes()
                    a = Path(pair["after"]["rawJson"][kind]["path"]).read_bytes()
                    equivalent(loads(b), loads(a))
                    if a != b:
                        raise ValueError("Before/after raw bytes differ: " + kind)
                    pair["after"].setdefault("beforeComparison", {})[kind] = {"sameBytes":a == b,
                        "sameNumericBitsAndStructure":True, "lexicalChangeOnly":False,
                        "beforeSha256":hashlib.sha256(b).hexdigest(), "afterSha256":hashlib.sha256(a).hexdigest()}
                save(out / "progress.json", receipt)
        for tag in identities:
            if identity(tag) != identities[tag]:
                raise ValueError("Linked identity changed")
        if sha(prepared["source"]["path"]) != prepared["source"]["sha256"]:
            raise ValueError("Source changed")
        if correctness_gates() != quiet:
            raise ValueError("Final runtime/gate/source binding changed")
        receipt.update(status="passed", completedProcesses=48, rawMetricValues=5280, pairedStageMetricMedians=880,
                       uniqueParserOutcomeCases=36, parserOutcomeEvaluations=1728,
                       summary=summarize(prepared["cases"], receipt["records"]))
        save(out / "summary.json", receipt); save(D / "serialization-results.json", receipt)
        print("PASS 8 cases / 48 processes / 22 stages / 5280 raw metric values", flush=True)
    except BaseException as error:
        receipt.update(status="failed", error=repr(error), completedProcesses=len(receipt["records"]))
        save(out / "failure.json", receipt); save(out / "progress.json", receipt)
        raise

if __name__ == "__main__":
    main()

capacity_probe.rs.text:
//! Public profile observation only: seed, correctness, JSON, and file writes
//! remain outside the 31 groups of 256 timed profile calls.
use pine_runtime::{
    Bar, HistoricalRuntime, PineValue, RuntimeResult, public_runtime_profiled_result_json,
};
use pine_sema::analyze_source;
use pine_syntax::{Severity, SourceFile};
use serde_json::{Value, json};
use std::hint::black_box;
use std::time::Instant;

const GROUPS: usize = 31;
const CALLS_PER_GROUP: usize = 256;

fn quarter_ticks(index: usize) -> u64 {
    400 + (index % 17) as u64
}

fn bar(index: usize) -> Bar {
    let close = quarter_ticks(index) as f64 / 4.0;
    Bar {
        time: 1_700_000_000 + index as i64 * 60,
        open: close,
        high: close + 1.0,
        low: close - 1.0,
        close,
        volume: 100.0,
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    if !(3..=4).contains(&args.len()) {
        return Err("usage: capacity_probe source.pine window [output.json]".into());
    }
    let window: usize = args[2].parse()?;
    if ![14, 129, 5000, 100_000, 1_000_000].contains(&window) {
        return Err("window must be one of 14, 129, 5000, 100000, 1000000".into());
    }
    let bars = window + 1000;
    let source = SourceFile::new("capacity_probe.pine", std::fs::read_to_string(&args[1])?);
    let analyze_started = Instant::now();
    let analysis = analyze_source(&source);
    let analyze_ms = analyze_started.elapsed().as_secs_f64() * 1000.0;
    if analysis
        .diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Error)
    {
        return Err(format!("{:?}", analysis.diagnostics).into());
    }
    let hir = analysis.hir.ok_or("no HIR")?;
    let mut runtime = HistoricalRuntime::new(&hir);
    let seed_started = Instant::now();
    for index in 0..bars {
        runtime
            .append_bar(bar(index))
            .map_err(|error| error.message)?;
    }
    let seed_ms = seed_started.elapsed().as_secs_f64() * 1000.0;

    // The direct oracle accumulates integer quarter ticks, so every sum is
    // exact before the final f64 conversion and mean. It shares no rolling
    // state, undo, or capacity logic with the runtime.
    let integer_sum = (bars - window..bars).map(quarter_ticks).sum::<u64>();
    let expected = (integer_sum as f64 / 4.0) / window as f64;
    let result_started = Instant::now();
    let result = runtime.result_view();
    if result.plots.len() != 1 {
        return Err("fixture must produce exactly one SMA plot".into());
    }
    let last = match result.plots[0].values.iter().last() {
        Some(PineValue::Float(value)) => *value,
        Some(PineValue::Int(value)) => *value as f64,
        _ => return Err("final SMA is missing or nonnumeric".into()),
    };
    let plot_values = result.plots[0].values.len();
    drop(result);
    let result_ms = result_started.elapsed().as_secs_f64() * 1000.0;
    if last.to_bits() != expected.to_bits() {
        return Err(format!(
            "SMA bits mismatch: {:016x} != {:016x}",
            last.to_bits(),
            expected.to_bits()
        )
        .into());
    }

    let expected_profile = runtime.profile();
    if expected_profile.bars != bars {
        return Err("profile bar count mismatch".into());
    }
    for _ in 0..64 {
        black_box(black_box(&runtime).profile());
    }
    let mut groups_ms = [0.0; GROUPS];
    for elapsed in &mut groups_ms {
        let started = Instant::now();
        for _ in 0..CALLS_PER_GROUP {
            black_box(black_box(&runtime).profile());
        }
        *elapsed = started.elapsed().as_secs_f64() * 1000.0;
    }
    if runtime.profile() != expected_profile {
        return Err("profile observation changed runtime counters".into());
    }
    let mut sorted = groups_ms;
    sorted.sort_by(f64::total_cmp);
    let median_per_call_ns = sorted[GROUPS / 2] * 1_000_000.0 / CALLS_PER_GROUP as f64;

    // Use the public profiled result encoder with an empty output payload to
    // retain every public profile field without serializing the bar history.
    let profile_document =
        public_runtime_profiled_result_json(&RuntimeResult::default(), &expected_profile);
    let mut profile_document: Value = serde_json::from_str(&profile_document)?;
    let profile_json = profile_document["profile"].take();
    let profile_field_count = profile_json
        .as_object()
        .ok_or("public encoder omitted profile object")?
        .len();
    let receipt = json!({
        "probe": "publicProfileCapacity",
        "source": args[1],
        "window": window,
        "bars": bars,
        "groups": GROUPS,
        "callsPerGroup": CALLS_PER_GROUP,
        "timedCalls": GROUPS * CALLS_PER_GROUP,
        "warmupCalls": 64,
        "groupMs": groups_ms,
        "profileMedianPerCallNs": median_per_call_ns,
        "analyzeMs": analyze_ms,
        "seedMs": seed_ms,
        "resultObservationMs": result_ms,
        "measurementScope": "31 groups of 256 public HistoricalRuntime::profile calls; full profile and runtime reference are black-boxed",
        "profileScope": "all fields emitted by public_runtime_profiled_result_json",
        "profileFieldCount": profile_field_count,
        "profile": profile_json,
        "profileUnchanged": true,
        "plotValues": plot_values,
        "lastSmaBits": format!("{:016x}", last.to_bits()),
        "oracleSmaBits": format!("{:016x}", expected.to_bits()),
        "oracleIntegerQuarterTicks": integer_sum,
        "oracleWindowStart": bars - window,
        "oracleWindowEndExclusive": bars,
        "oracle": "direct integer sum of (400 + index % 17), divided by 4 and the window after the exact sum",
    });
    let encoded = serde_json::to_string(&receipt)?;
    if let Some(output) = args.get(3) {
        std::fs::write(output, &encoded)?;
    }
    println!("{encoded}");
    Ok(())
}

capacity_runner.py.text:
"""Focused public profile observation receipts; never builds or links.

Preparation only writes fixed Pine fixtures and a plan. Execution requires the
final frozen source, both complete gates, release, and both after-link phases.
The coordinator runs this separately from serialization measurements.
"""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
import math
import os
from pathlib import Path
import re
import statistics
import struct
import subprocess

from evidence_common import D, ROOT, directory, execute, save, sha, source
from serialization_runner import identity, integer, loads, read

WINDOWS = (14, 129, 5000, 100_000, 1_000_000)
GROUPS = 31
CALLS = 256
REPETITIONS = 3
TIMINGS = (
    "profileMedianPerCallNs", "analyzeMs", "seedMs", "resultObservationMs",
)
TOP = {
    "probe", "source", "window", "bars", "groups", "callsPerGroup",
    "timedCalls", "warmupCalls", "groupMs", *TIMINGS, "measurementScope",
    "profileScope", "profileFieldCount", "profile", "profileUnchanged",
    "plotValues", "lastSmaBits", "oracleSmaBits", "oracleIntegerQuarterTicks",
    "oracleWindowStart", "oracleWindowEndExclusive", "oracle",
}
PROFILE_SOURCE = ROOT / "crates/pine-runtime/src/output/json/profile.rs"
PHASE_NAMES = (
    "gate-windows", "gate-linux", "release", "link-serialization-after",
    "link-capacity-after",
)


def profile_fields():
    # Derive the complete public schema from the source of the public encoder,
    # rather than selecting a favorable subset of observed counters.
    fields = re.findall(r'\\"([A-Za-z][A-Za-z0-9]*)\\":',
                        PROFILE_SOURCE.read_text(encoding="utf8"))
    if len(fields) < 100 or len(fields) != len(set(fields)):
        raise ValueError("Unexpected public profile encoder schema")
    return sorted(fields)


def prepare():
    cases = []
    for window in WINDOWS:
        text = ("//@version=6\nindicator(\"capacity profile\")\n"
                f"plot(ta.sma(close, {window}))\n")
        path = D / f"capacity-sma-{window}.pine"
        cases.append({"name": f"sma{window}", "window": window,
                      "bars": window + 1000, "source": source(path, text)})
    plan = {
        "cases": cases, "repetitionsPerVersion": REPETITIONS,
        "plannedProcesses": len(WINDOWS) * REPETITIONS * 2,
        "groupsPerProcess": GROUPS, "callsPerGroup": CALLS,
        "timedCallsPerProcess": GROUPS * CALLS,
        "timingFields": list(TIMINGS),
        "profileSchema": {"path": str(PROFILE_SOURCE), "sha256": sha(PROFILE_SOURCE),
                          "fields": profile_fields()},
        "scope": "Public HistoricalRuntime::profile observation; control timings are not whole-runtime performance qualification",
        "fixture": "close=(400+index%17)/4; bars=window+1000; one SMA plot",
        "probesExecuted": False,
    }
    save(D / "capacity-plan.json", plan)
    return plan


def _phase(name, binding):
    path = D / f"phase-{name}.json"
    value = read(path)
    if (value.get("phase") != name or value.get("status") != "passed"
            or value.get("returncode") != 0
            or value.get("before") != binding or value.get("after") != binding):
        raise ValueError("Required phase did not pass against frozen source: " + name)
    if value.get("wrapperSha256") != sha(D / "run_phase.py"):
        raise ValueError("Phase wrapper identity differs: " + name)
    if value.get("wrapperLogSha256") != sha(D / f"phase-{name}-wrapper.log"):
        raise ValueError("Phase wrapper log differs: " + name)
    if name.startswith("gate-"):
        log, exit_path = D / f"{name}.log", D / f"{name}.exit"
        if int(exit_path.read_text(encoding="utf-8-sig")) != 0:
            raise ValueError("Full gate exit is nonzero: " + name)
        hashes = {"gateLogSha256": sha(log), "gateExitSha256": sha(exit_path)}
    elif name == "release":
        log, exit_path = D / "build-release.log", D / "build-release.exit"
        if int(exit_path.read_text(encoding="utf-8-sig")) != 0:
            raise ValueError("Release build exit is nonzero")
        hashes = {"buildLogSha256": sha(log), "buildExitSha256": sha(exit_path)}
    else:
        _, probe, tag = name.split("-")
        hashes = {
            "linkReceiptSha256": sha(D / f"identity-{probe}-{tag}.json"),
            "linkLogSha256": sha(D / f"link-{probe}-{tag}.log"),
        }
    if any(value.get(key) != expected for key, expected in hashes.items()):
        raise ValueError("Required phase artifact differs: " + name)
    return {"path": str(path), "sha256": sha(path), "artifactHashes": hashes}


def no_other_measurements():
    # Reject a serialization runner even between its child processes, and
    # reject another capacity runner. Only our own Python process is excluded.
    # No command lines are printed or retained.
    command = (
        "$ErrorActionPreference = 'Stop'; "
        "Get-CimInstance Win32_Process | Where-Object { "
        f"$_.ProcessId -ne {os.getpid()} -and ("
        "$_.Name -match '^(cargo|rustc|maturin|link|cl|msbuild|pine.*|serialization.*|capacity.*|heap.*|differential.*)\\.exe$' "
        "-or ($_.Name -match '^(python|pythonw)\\.exe$' -and "
        "$_.CommandLine -match '(serialization_runner|capacity_runner)\\.py')) "
        "} | Select-Object Name,ProcessId | ConvertTo-Json"
    )
    checked = subprocess.run(
        ["powershell.exe", "-NoProfile", "-Command", command], cwd=ROOT,
        capture_output=True, timeout=30,
    )
    if checked.returncode != 0:
        raise ValueError("Could not verify build/measurement quiescence")
    if checked.stdout.decode("utf-8-sig").strip():
        raise ValueError("Another build, validation, or measurement process is active")
    return {
        "matchingWindowsBuildOrMeasurementProcesses": [],
        "otherSerializationOrCapacityRunners": [],
        "limitation": "Coordinator keeps WSL compilation and other measurements quiescent; this is not proof of OS inactivity or a shared serialization lock.",
    }


def prerequisites(prepared):
    manifest_path = D / "source-identity.json"
    manifest = read(manifest_path)
    if len(manifest["files"]) != 6319:
        raise ValueError("Expected final 6319-file source manifest")
    changed = [path for path, expected in manifest["files"].items()
               if not (ROOT / path).is_file() or sha(ROOT / path) != expected]
    if changed:
        raise ValueError("Frozen source differs: " + repr(changed))
    binding = {
        "manifestSha256": sha(manifest_path), "archiveSha256": sha(D / "source.tar"),
        "files": 6319, "sourceVerified": True,
    }
    phases = {name: _phase(name, binding) for name in PHASE_NAMES}
    identities = {tag: identity(tag, "capacity") for tag in ("before", "after")}
    serialization_after = identity("after", "serialization")
    if (identities["before"]["sourceSha256"] != identities["after"]["sourceSha256"]
            or identities["after"]["sourceManifestSha256"] != binding["manifestSha256"]
            or serialization_after["sourceManifestSha256"] != binding["manifestSha256"]):
        raise ValueError("Capacity before/after probe or final linked source identity differs")
    for case in prepared["cases"]:
        if sha(Path(case["source"]["path"])) != case["source"]["sha256"]:
            raise ValueError("Prepared Pine fixture changed")
    schema = prepared["profileSchema"]
    if sha(PROFILE_SOURCE) != schema["sha256"] or profile_fields() != schema["fields"]:
        raise ValueError("Public profile encoder schema changed")
    return {
        "sourceBinding": binding, "phases": phases, "identities": identities,
        "serializationAfterIdentity": serialization_after,
        "quiescence": no_other_measurements(),
    }


def quarter_prefix(end):
    cycles, remainder = divmod(end, 17)
    return cycles * 136 + remainder * (remainder - 1) // 2


def oracle(case):
    end, start = case["bars"], case["bars"] - case["window"]
    ticks = 400 * case["window"] + quarter_prefix(end) - quarter_prefix(start)
    value = (float(ticks) / 4.0) / case["window"]
    return {"quarterTicks": ticks, "start": start, "end": end,
            "smaBits": struct.pack("!d", value).hex()}


def numeric(value, positive=False):
    if (isinstance(value, bool) or not isinstance(value, (int, float))
            or not math.isfinite(value) or value < 0 or (positive and value == 0)):
        raise ValueError("Expected finite nonnegative timing")
    return value


def parse_metrics(raw, case, schema):
    lines = raw.splitlines()
    if len(lines) != 1 or not lines[0]:
        raise ValueError("Expected one capacity metrics JSON line")
    metrics = loads(lines[0])
    if not isinstance(metrics, dict) or set(metrics) != TOP:
        raise ValueError("Unknown or missing capacity metrics field")
    expected = {
        "probe": "publicProfileCapacity", "source": case["source"]["path"],
        "window": case["window"], "bars": case["bars"], "groups": GROUPS,
        "callsPerGroup": CALLS, "timedCalls": GROUPS * CALLS, "warmupCalls": 64,
        "profileUnchanged": True, "plotValues": case["bars"],
        "measurementScope": "31 groups of 256 public HistoricalRuntime::profile calls; full profile and runtime reference are black-boxed",
        "profileScope": "all fields emitted by public_runtime_profiled_result_json",
        "oracle": "direct integer sum of (400 + index % 17), divided by 4 and the window after the exact sum",
    }
    for key, value in expected.items():
        if type(metrics[key]) is not type(value) or metrics[key] != value:
            raise ValueError("Unexpected capacity fixture field: " + key)
    for field in TIMINGS:
        numeric(metrics[field], positive=field == "profileMedianPerCallNs")
    groups = metrics["groupMs"]
    if not isinstance(groups, list) or len(groups) != GROUPS:
        raise ValueError("Expected 31 profile timing groups")
    for value in groups:
        numeric(value, positive=True)
    calculated = statistics.median(groups) * 1_000_000.0 / CALLS
    if struct.pack("!d", float(metrics["profileMedianPerCallNs"])) != struct.pack("!d", calculated):
        raise ValueError("Profile per-call nanosecond median does not recompute")
    proof = oracle(case)
    for field, value in (
        ("lastSmaBits", proof["smaBits"]), ("oracleSmaBits", proof["smaBits"]),
        ("oracleIntegerQuarterTicks", proof["quarterTicks"]),
        ("oracleWindowStart", proof["start"]),
        ("oracleWindowEndExclusive", proof["end"]),
    ):
        if type(metrics[field]) is not type(value) or metrics[field] != value:
            raise ValueError("Independent quarter-integer SMA oracle differs: " + field)
    profile = metrics["profile"]
    if not isinstance(profile, dict) or sorted(profile) != schema["fields"]:
        raise ValueError("Public profile counters are missing or unexpected")
    if integer(metrics["profileFieldCount"]) != len(schema["fields"]):
        raise ValueError("Full public profile field count differs")
    for key, value in profile.items():
        if key == "historyRetentionMode":
            if value not in {"staticTrimmed", "dynamicFull", "maxBarsBack"}:
                raise ValueError("Unexpected history retention mode")
        elif key == "historyHasDynamicOffsets":
            if type(value) is not bool:
                raise ValueError("Expected history dynamic-offset flag")
        elif value is None and key in {"historyMaxBarsBack", "historyDynamicRetentionMaxMissedOffset"}:
            continue
        elif integer(value) < 0:
            raise ValueError("Negative public profile counter: " + key)
    if profile["bars"] != case["bars"] or profile["plots"] != 1 or profile["plotValues"] != case["bars"]:
        raise ValueError("Public profile bar/plot counts differ")
    return metrics, proof


def summary(cases, records):
    result = {}
    for case in cases:
        by_tag = {tag: [row for row in records
                        if row["case"] == case["name"] and row["tag"] == tag]
                  for tag in ("before", "after")}
        if any(len(rows) != REPETITIONS for rows in by_tag.values()):
            raise ValueError("Incomplete capacity repetition set")
        reference = by_tag["before"][0]["metrics"]["profile"]
        if any(row["metrics"]["profile"] != reference
               for rows in by_tag.values() for row in rows):
            raise ValueError("Full public profile fields differ across versions or repetitions")
        timings = {}
        for name in TIMINGS:
            before = [row["metrics"][name] for row in by_tag["before"]]
            after = [row["metrics"][name] for row in by_tag["after"]]
            bm, am = statistics.median(before), statistics.median(after)
            timings[name] = {
                "unit": "ns/call" if name == "profileMedianPerCallNs" else "ms",
                "beforeSamples": before, "afterSamples": after,
                "beforeMedian": bm, "afterMedian": am,
                "beforeMin": min(before), "beforeMax": max(before),
                "afterMin": min(after), "afterMax": max(after),
                "afterBeforeRatio": am / bm if bm else None,
            }
        result[case["name"]] = {
            "window": case["window"], "bars": case["bars"], "timings": timings,
            "fullProfile": reference, "profileFieldCount": len(reference),
            "beforeAfterAllProfileFieldsEqual": True,
            "oracle": oracle(case),
            "profileGroupMs": {tag: [row["metrics"]["groupMs"] for row in rows]
                               for tag, rows in by_tag.items()},
        }
    return result


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    modes = ap.add_mutually_exclusive_group(required=True)
    modes.add_argument("--prepare-only", action="store_true")
    modes.add_argument("--execute", action="store_true")
    ap.add_argument("--timeout", type=float, default=300)
    args = ap.parse_args()
    numeric(args.timeout, positive=True)
    prepared = prepare()
    if args.prepare_only:
        print("Prepared 5 cases / 30 processes; no builds or probes executed.")
        return
    initial = prerequisites(prepared)
    plan_path = D / "capacity-plan.json"
    plan_sha = sha(plan_path)
    runner_sha = sha(Path(__file__))
    out = directory("capacity")
    copied_cases = []
    for case in prepared["cases"]:
        original = case["source"]
        frozen = out / "sources" / Path(original["path"]).name
        frozen.parent.mkdir(parents=True, exist_ok=True)
        frozen.write_bytes(Path(original["path"]).read_bytes())
        if sha(frozen) != original["sha256"]:
            raise ValueError("Copied Pine fixture differs")
        copied_cases.append({**case, "originalSource": original,
                             "source": {"path": str(frozen), "sha256": sha(frozen)}})
    receipt = {
        "status": "running", "startedUtc": datetime.now(timezone.utc).isoformat(),
        "plannedProcesses": 30, "completedProcesses": 0,
        "method": "5 fixed windows; 3 fresh processes per version; before/after order alternates by repetition; all processes run sequentially",
        "prerequisites": initial, "runnerSha256": runner_sha,
        "helperHashes": {name: sha(D / name) for name in ("evidence_common.py", "serialization_runner.py")},
        "plan": {"path": str(plan_path), "sha256": plan_sha},
        "profileSchema": prepared["profileSchema"], "cases": copied_cases,
        "records": [],
        "limits": [
            "The profile timing includes all work performed by public HistoricalRuntime::profile, including walks of other state collections.",
            "Seed, analysis, result observation, encoder work and receipt writes are outside the timed profile groups; control timings do not establish zero overhead.",
            "resultObservationMs includes result_view construction, last-value access and view disposal; it is not pure view-construction timing.",
            "Three fresh-process medians are descriptive; this is not whole-process RSS or a full resource matrix qualification.",
            "The coordinator schedules serialization and capacity measurement separately; runner checks reject active peer runners and probes before every process.",
        ],
    }
    save(out / "progress.json", receipt)
    try:
        for repetition in range(REPETITIONS):
            for case in copied_cases:
                pair = {}
                tags = ("before", "after") if repetition % 2 == 0 else ("after", "before")
                for tag in tags:
                    no_other_measurements()
                    stem = f'{case["name"]}-{tag}-{repetition}'
                    metrics_file = out / (stem + ".metrics.json")
                    command = [initial["identities"][tag]["binary"], case["source"]["path"],
                               str(case["window"]), str(metrics_file)]
                    run, raw = execute(out, stem, command, args.timeout)
                    row = {"case": case["name"], "tag": tag, "repetition": repetition,
                           "source": case["source"], "run": run}
                    receipt["records"].append(row)
                    receipt["completedProcesses"] = sum(r["run"]["returncode"] == 0 for r in receipt["records"])
                    save(out / "progress.json", receipt)
                    if run["returncode"] != 0:
                        raise RuntimeError("Capacity process failed: " + stem)
                    if Path(run["stderr"]).read_bytes():
                        raise ValueError("Unexpected capacity process stderr: " + stem)
                    if metrics_file.read_bytes() != raw.rstrip(b"\r\n"):
                        raise ValueError("Metrics file differs from raw stdout")
                    row["metrics"], row["pythonOracle"] = parse_metrics(raw, case, prepared["profileSchema"])
                    row["rawMetrics"] = {"path": str(metrics_file), "sha256": sha(metrics_file),
                                         "bytes": metrics_file.stat().st_size}
                    pair[tag] = row
                    save(out / "progress.json", receipt)
                    print(stem, "profileNsPerCall", row["metrics"]["profileMedianPerCallNs"], flush=True)
                if pair["before"]["metrics"]["profile"] != pair["after"]["metrics"]["profile"]:
                    raise ValueError("Paired complete profile fields differ")
                pair["after"]["beforeComparison"] = {
                    "allPublicProfileFieldsEqual": True, "smaBitsEqualToIndependentOracle": True,
                    "beforeStdoutSha256": pair["before"]["run"]["stdoutSha256"],
                    "afterStdoutSha256": pair["after"]["run"]["stdoutSha256"],
                }
                save(out / "progress.json", receipt)
        if prerequisites(prepared) != initial:
            raise ValueError("Final gates, source, links, libraries or quiescence differ")
        if sha(plan_path) != plan_sha or sha(Path(__file__)) != runner_sha:
            raise ValueError("Plan or runner changed during measurement")
        for name, expected in receipt["helperHashes"].items():
            if sha(D / name) != expected:
                raise ValueError("Receipt helper changed during measurement")
        for case in copied_cases:
            if sha(Path(case["source"]["path"])) != case["source"]["sha256"]:
                raise ValueError("Archived Pine fixture changed")
        for row in receipt["records"]:
            for name in ("stdout", "stderr", "exit"):
                if sha(Path(row["run"][name])) != row["run"][name + "Sha256"]:
                    raise ValueError("Raw subprocess receipt changed")
            if sha(Path(row["rawMetrics"]["path"])) != row["rawMetrics"]["sha256"]:
                raise ValueError("Raw metrics file changed")
        receipt.update(
            status="passed", finishedUtc=datetime.now(timezone.utc).isoformat(),
            completedProcesses=30, rawTimingValues=120, pairedTimingMedians=20,
            rawProfileGroupTimingValues=930, timedProfileCalls=238080,
            fullProfileComparisons=15, uniqueSmaOracleCases=5,
            summary=summary(copied_cases, receipt["records"]),
        )
        save(out / "summary.json", receipt)
        save(D / "capacity-results.json", receipt)
        print("PASS 5 windows / 30 fresh processes / 930 groups / 238080 timed profile calls", flush=True)
    except BaseException as error:
        receipt.update(status="failed", error=repr(error),
                       attemptedProcesses=len(receipt["records"]))
        save(out / "failure.json", receipt)
        save(out / "progress.json", receipt)
        raise


if __name__ == "__main__":
    main()
